"use client";

import { useState } from "react";
import {
  type TiltEqState,
  tiltEqDevice,
} from "@/components/audio-ui/devices/tilt-eq/device";
import { createTiltEqEngine } from "@/components/audio-ui/devices/tilt-eq/engine";
import { TiltEqPanel } from "@/components/audio-ui/devices/tilt-eq/panel";
import { useDeviceLoop } from "@/hooks/use-device-loop";
import { useMasterBus } from "@/hooks/use-master-bus";

const MASTER_VOLUME = 0.7;

/**
 * A tilt EQ you can plug in: its state, a panel that draws the curve it tilts
 * and an engine that plays it, each its own file and none knowing the others.
 * Play the loop and turn the tilt: brighter one way, darker the other.
 */
export function BlockTiltEq() {
  const [state, setState] = useState<TiltEqState>(() =>
    tiltEqDevice.defaults()
  );
  const master = useMasterBus(MASTER_VOLUME);
  useDeviceLoop({
    create: createTiltEqEngine,
    destination: master,
    state,
  });
  return (
    <div className="rounded-2xl h-full w-full min-w-0">
      <TiltEqPanel onValueChange={setState} value={state} />
    </div>
  );
}
